xwikidoc.content:
{{velocity}} #** * Displays one field of an entry as a definition list item, with a label element bound to the generated input. The * label is what gives the input its accessible name and what makes clicking the label text focus the field: a bare * definition term text node does neither. * * The label text is the translated pretty name of the field, which is also what the object editor and the Live Data * of the home page name that field with. A sheet declaring a label of its own is a label free to drift from the one * the very same field carries everywhere else. * * @param $object the object holding the property, which together with the property name gives the input identifier * that XWiki generates * @param $propertyName the name of the property to display in edit mode * @param $fieldIdSuffix appended to the generated input identifier, for the displayers that name their input apart * (the empty string for all the standard ones) *# #macro (displayEntryField $object $propertyName $fieldIdSuffix) #set ($fieldId = "${object.getxWikiClass().getName()}_${object.number}_${propertyName}$!{fieldIdSuffix}") #set ($fieldLabel = $object.getxWikiClass().get($propertyName).translatedPrettyName) ; {{html clean="false"}}<label for="$escapetool.xml($fieldId)">$escapetool.xml($fieldLabel)</label>{{/html}} : $doc.display($propertyName, 'edit', $object) #end #macro (handleAddAction $product $version $queryString) #if ("$!version" == '') {{error}}{{translation key="releasenotes.entry.versionRequired"/}}{{/error}}
#else ## The page is taken through the API, which refuses a product it cannot resolve and a page it cannot save. The ## caller is a form, so a refusal is reported to its author as a message rather than left to break the page the ## form sits on. #try('reserveException') #set ($entryPageReference = $services.releasenotes.reserveNextEntry($product, $version)) #set ($shortVersion = $services.releasenotes.getReleaseNoteReference($product, $version).parent.name) #end ## A change is only added to a release note that exists: the form of the home page lets its author type any ## version, and a page taken under a release note that does not exist would hold a change nothing lists. The API ## refuses it, and the author is told why rather than handed the generic failure. The exception is wrapped by the ## Velocity call that threw it, hence the look through its causes, and it is recognised by its string form, which ## starts with its class name, because the methods of a Class cannot be called from Velocity. #set ($releaseNoteNotFound = false) #if ($reserveException) #foreach ($throwable in $exceptiontool.getThrowableList($reserveException)) #if ($throwable.toString().startsWith('org.xwiki.contrib.releasenotes.ReleaseNotesNotFoundException:')) #set ($releaseNoteNotFound = true) #end #end #end #if ($releaseNoteNotFound) {{error}}{{translation key="releasenotes.entry.releaseNoteNotFound"/}}{{/error}}
#elseif ($reserveException) {{error}}{{translation key="releasenotes.entry.addFailed"/}}{{/error}}
#elseif ("$!entryPageReference" == '') {{error}}{{translation key="releasenotes.entry.notReserved"/}}{{/error}}
#else ## The form of the new entry is opened with the "edit" action and the inline editor, and not with the "inline" ## action, which is deprecated and only exists in the legacy module. $response.sendRedirect($xwiki.getURL($entryPageReference, 'edit', "$!{queryString}&editor=inline&shortVersion=${escapetool.url($shortVersion)}")) #end #end #end
